function closeThemeMenu(){const menu=$("#themeMenu");const wasOpen=state.themeMenuOpen;state.themeMenuOpen=false;renderThemeButton();if(!menu||menu.classList.contains("hidden")){if(wasOpen)unlockScroll();return}menu.classList.remove("open");menu.classList.add("closing");setTimeout(()=>menu.classList.add("hidden"),180);if(wasOpen)unlockScroll()}
function toggleTheme(){toggleThemeMenu(event)}
document.addEventListener("click",e=>{if(!e.target.closest("#themeMenu")&&!e.target.closest("#themeToggle"))closeThemeMenu();const s=$(".sidebar");if(!s||!s.classList.contains("open"))return;if(e.target.closest(".sidebar")||e.target.closest(".mobile-only"))return;s.classList.remove("open")});
function loadPageCache(){try{return JSON.parse(sessionStorage.adbPageCache||"{}")}catch{return {}}}
function savePageCache(){try{sessionStorage.adbPageCache=JSON.stringify(state.cache)}catch{}}
function invalidateCache(...keys){keys.forEach(k=>delete state.cache[k]);savePageCache()}
function updatePageCache(key,data){state.cache[key]={ts:Date.now(),data};savePageCache();return data}
function refreshCacheInBackground(key,url){if(state.inflight[key])return state.inflight[key];state.inflight[key]=req(url).then(data=>updatePageCache(key,data)).catch(e=>console.debug("prefetch failed",key,e)).finally(()=>delete state.inflight[key]);return state.inflight[key]}
async function cachedReq(key,url,ttl=120000){const c=state.cache[key];if(c&&ttl!==0){if(Date.now()-c.ts>ttl)refreshCacheInBackground(key,url);return c.data}if(state.inflight[key])return state.inflight[key];state.inflight[key]=req(url).then(data=>updatePageCache(key,data)).finally(()=>delete state.inflight[key]);return state.inflight[key]}
function warmPage(p){({dashboard:()=>refreshCacheInBackground("dashboard","/api/dashboard"),astrbot:()=>{refreshCacheInBackground("astrbot","/api/astrbot");refreshCacheInBackground("plugins:astrbot","/api/plugins/astrbot")},napcat:()=>refreshCacheInBackground("napcat","/api/napcat"),pool:()=>refreshCacheInBackground("pool","/api/napcat/pool"),files:()=>refreshCacheInBackground("files","/api/files"),backup:()=>refreshCacheInBackground("backup","/api/backups"),settings:()=>{refreshCacheInBackground("settings","/api/settings");refreshCacheInBackground("https","/api/https/status");refreshCacheInBackground("watchdog","/api/watchdog/status")}}[p]||(()=>{}))()}
function startPagePrefetch(){if(state.prefetchStarted)return;state.prefetchStarted=true;["napcat","pool","astrbot","files","settings","backup"].forEach((p,i)=>setTimeout(()=>warmPage(p),350+i*280))}
function pageHasWarmData(p){const map={dashboard:["dashboard"],astrbot:["astrbot"],napcat:["napcat"],pool:["pool"],files:["files"],backup:["backup"],settings:["settings"]};return (map[p]||[]).some(k=>state.cache[k])}
function pageShell(p){if(["dashboard","update","account","logs"].includes(p)||pageHasWarmData(p))return;const meta=pages.find(x=>x[0]===p)||pages[0];$("#content").innerHTML=`<section class="grid page-skeleton"><div class="card span12 page-head"><div><h3>${safeText(meta[2])}</h3><p class="muted">${"\u6b63\u5728\u51c6\u5907\u6700\u65b0\u5185\u5bb9..."}</p></div></div>${Array.from({length:6},(_,i)=>`<div class="card ${i<2?'span6':'span4'} skeleton-card"><span></span><b></b><em></em></div>`).join("")}</section>`}
function pageStillActive(page,seq){return page===state.page && seq===state.renderSeq}
function userEditingForm(){const el=document.activeElement;return !!(el&&["INPUT","TEXTAREA","SELECT"].includes(el.tagName))}

async function refresh(rerender=true,force=false){try{if(force)invalidateCache("dashboard","astrbot","plugins:astrbot","napcat","pool","settings","https","watchdog");state.data=await cachedReq("dashboard","/api/dashboard",force?0:60000);const ok=state.data.astrbot.running;$("#globalStatus").className="status-pill "+(ok?"green":"red");$("#globalStatus").textContent=ok?"运行中":"异常";if(rerender)render()}catch(e){console.log(e)}}
function title(t,s){const full=`\u6dcb\u96e8-${t}`;document.title=full;$("#pageTitle").textContent=full;$("#pageSub").textContent=s}
function fmtBytes(n){if(!n)return "0 B";const u=["B","KB","MB","GB","TB"];let i=0;while(n>1024&&i<u.length-1){n/=1024;i++}return n.toFixed(i?1:0)+" "+u[i]}
function statusText(s){return {running:"\u8fd0\u884c\u4e2d",exited:"\u5df2\u505c\u6b62",created:"\u5df2\u521b\u5efa",restarting:"\u91cd\u542f\u4e2d",paused:"\u5df2\u6682\u505c",dead:"\u5f02\u5e38",missing:"\u4e0d\u5b58\u5728",unknown:"\u672a\u77e5"}[s]||s||"\u672a\u77e5"}
function botName(n){const m=String(n||"").match(/^napcat0*(\d+)$/);return m?`\u673a\u5668\u4eba${Number(m[1])}`:(n||"\u673a\u5668\u4eba")}
function statusBadge(s){let c=s==="running"?"green":s==="exited"?"grey":s==="missing"?"red":s==="dead"?"red":"blue";return `<span class="status-pill ${c}">${safeText(statusText(s))}</span>`}
function taskStatusText(s){return {pending:"\u7b49\u5f85\u4e2d",running:"\u6267\u884c\u4e2d",success:"\u5df2\u5b8c\u6210",failed:"\u5931\u8d25",cancelled:"\u5df2\u53d6\u6d88"}[s]||statusText(s)}
function displayTargetName(n){return n==="astrbot"?"AstrBot \u4e3b\u670d\u52a1":n==="deploy"?"\u90e8\u7f72\u811a\u672c":n==="panel"?"Web \u9762\u677f":botName(n)}
async function copy(t){return copyText(t)}
async function copyText(t){const text=String(t??"");try{if(navigator.clipboard?.writeText&&window.isSecureContext!==false){await navigator.clipboard.writeText(text);toast("\u5df2\u590d\u5236");return true}}catch{}try{const ta=document.createElement("textarea");ta.value=text;ta.setAttribute("readonly","");ta.style.cssText="position:fixed;left:-9999px;top:0;font-size:16px";document.body.appendChild(ta);ta.focus();ta.select();ta.setSelectionRange(0,ta.value.length);const ok=document.execCommand("copy");ta.remove();toast(ok?"\u5df2\u590d\u5236":"\u590d\u5236\u5931\u8d25\uff0c\u8bf7\u957f\u6309\u6587\u672c\u624b\u52a8\u590d\u5236");return ok}catch(e){toast("\u590d\u5236\u5931\u8d25\uff0c\u8bf7\u957f\u6309\u6587\u672c\u624b\u52a8\u590d\u5236");return false}}
function activeButton(){const el=document.activeElement;return el&&el.tagName==="BUTTON"?el:null}
async function withBusy(label,fn){
  if(state.busy){toast("\u5df2\u6709\u4efb\u52a1\u6b63\u5728\u5904\u7406\uff0c\u8bf7\u7a0d\u7b49");return}
  const el=activeButton(); state.busy=true;
  if(el){el.dataset.oldText=el.innerHTML;el.disabled=true;el.classList.add("is-busy");el.innerHTML=`<span class="spin"></span>${label||"\u5904\u7406\u4e2d"}`}
  toast(label||"\u6b63\u5728\u5904\u7406\uff0c\u8bf7\u7a0d\u7b49");
  try{return await fn()}finally{setTimeout(()=>{state.busy=false;if(el){el.disabled=false;el.classList.remove("is-busy");el.innerHTML=el.dataset.oldText||el.innerHTML}},900)}
}
function render(){
  if(state.page!=="logs")closeLiveLog?.();
  const seq=++state.renderSeq, page=state.page, p=pages.find(x=>x[0]===page)||pages[0];
  title(p[2],p[3]);
  $("#content")?.classList.add("page-in");
  pageShell(page);
  Promise.resolve(({dashboard,astrbot,napcat,pool,logs,files,backup,update,account,settings}[page]||dashboard)(page,seq)).catch(e=>{
    if(seq!==state.renderSeq||page!==state.page)return;
    console.error(e);
    $("#content").innerHTML=`<section class="grid"><div class="card span12"><h3>${"\u52a0\u8f7d\u5931\u8d25"}</h3><p class="muted">${safeText(e.message||e)}</p><button class="primary" onclick="render()">${"\u91cd\u8bd5"}</button></div></section>`
  })
}

function dashboard(){const d=state.data||{};$("#content").innerHTML=`<section class="grid">
${!d.deployed?deployWizard():""}
${kpi("bot","AstrBot",d.astrbot?.running?"运行中":"异常",d.astrbot?.running?"i-green":"i-red")}
${kpi("nodes","机器人实例",String(d.napcats?.length||0),"i-blue")}
${kpi("docker","Docker",d.docker?.ok?"正常":"异常",d.docker?.ok?"i-green":"i-red")}
${kpi("disk","磁盘占用",(d.system?.disk?.used_percent||0)+"%","i-orange")}
<div class="card span6"><h3>服务健康状态</h3>${healthRows(d)}</div>
<div class="card span6"><h3>资源图表</h3>${metric(d)}</div>
<div class="card span7"><h3>端口占用</h3><pre class="code">${esc(d.ports||"暂无")}</pre></div>
<div class="card span5"><h3>最近操作记录</h3><pre class="code">${esc((d.recent||[]).join("\\n")||"暂无操作")}</pre></div>
</section>`}
function deployWizard(){return `<div class="card span12" style="background:linear-gradient(135deg,#2563eb22,#a855f722)"><h3>初始化部署向导</h3><p class="muted">当前还没有检测到完整部署信息。你可以在这里直接部署 AstrBot + 机器人，不需要再进 SSH 敲命令。</p><div class="toolbar"><label style="max-width:180px">机器人数量<input id="initNapCount" type="number" min="0" max="999" value="1"></label><label style="max-width:240px">连接 Token<input id="initToken" value="yuyu521521"></label><button class="primary" onclick="startDeploy()">开始自动部署</button></div><div class="muted">会自动创建机器人网络、AstrBot、机器人实例、反向 WebSocket 配置和 deploy_info.txt。</div></div>`}
async function startDeploy(){return withBusy("\u6b63\u5728\u521b\u5efa\u90e8\u7f72\u4efb\u52a1",async()=>{const napcat_count=Number($("#initNapCount").value||1),reverse_token=$("#initToken").value||"yuyu521521";const t=await req("/api/deploy/start",{method:"POST",body:JSON.stringify({napcat_count,reverse_token})});toast("\u521d\u59cb\u5316\u90e8\u7f72\u4efb\u52a1\u5df2\u5f00\u59cb");showTask(t.id)})}
function kpi(ic,label,value,cls){return `<div class="card span3 kpi"><div><div class="muted">${label}</div><strong>${value}</strong></div><div class="icon ${cls}">${icon(ic)}</div></div>`}
function healthRows(d){return `<div class="file-cards"><div class="file-card"><b>AstrBot 主服务</b>${statusBadge(d.astrbot?.status)}</div><div class="file-card"><b>机器人网络</b><span class="copyable">${safeText(d.network)}</span></div><div class="file-card"><b>公网 IP</b><span onclick="copy('${q(d.public_ip)}')">${safeText(d.public_ip)}</span></div><div class="file-card"><b>内网 IP</b><span>${safeText(d.private_ip)}</span></div></div>`}
function metric(d){let m=d.system?.memory||{},disk=d.system?.disk||{},load=(d.system?.load?.[0]||0);let cpu=Math.min(100,Math.round(load*25));return `<div class="chart-row"><div class="ring" style="--p:${cpu}"><b>${cpu}%</b></div><div class="ring" style="--p:${m.used_percent||0}"><b>${m.used_percent||0}%</b></div><div class="ring" style="--p:${disk.used_percent||0}"><b>${disk.used_percent||0}%</b></div><div class="file-cards" style="flex:1;min-width:220px"><div>CPU 负载估算：${load}</div><div>内存：${fmtBytes((m.total||0)-(m.available||0))} / ${fmtBytes(m.total||0)}</div><div>磁盘：${fmtBytes(disk.used||0)} / ${fmtBytes(disk.total||0)}</div><div class="mini-bars">${Array.from({length:18},(_,i)=>`<span style="height:${20+Math.abs(Math.sin(i+(m.used_percent||0)/20))*58}px"></span>`).join("")}</div></div></div>`}
async function astrbot(page="astrbot",seq=state.renderSeq){const a=await cachedReq("astrbot","/api/astrbot");if(!pageStillActive(page,seq))return;const pl=await cachedReq("plugins:astrbot","/api/plugins/astrbot").catch(()=>({base:"/opt/astrbot/data/plugins",plugins:[]}));if(!pageStillActive(page,seq))return;$("#content").innerHTML=`<section class="grid"><div class="card span4"><h3>AstrBot 状态</h3><div class="file-cards"><div class="info-line"><b>容器</b><span class="value">${statusBadge(a.status.status)}</span></div><div class="info-line"><b>WebUI</b><span class="value"><a class="link-pill" href="${safeHref(a.url)}" target="_blank" rel="noopener noreferrer">${safeText(a.url)}</a></span></div><div class="info-line"><b>账号</b><span class="value">${safeText(a.username)}</span></div><div class="info-line"><b>初始密码</b><span class="value copyable" onclick="copy('${q(a.password)}')">${a.password||"未解析"}</span></div><p class="muted password-note">如果你已经在 AstrBot 里修改过密码，请使用修改后的密码登录；这里显示的是 AstrBot 启动日志里的首次随机密码。</p><div class="info-line"><b>连接 Token</b><span class="value" onclick="copy('${q(a.token)}')">${safeText(a.token)}</span></div></div></div><div class="card span8 astr-action-card"><div class="section-head"><div><h3>\u64cd\u4f5c</h3><p class="muted">\u5e38\u7528\u63a7\u5236\u653e\u5728\u5de6\u4fa7\uff0c\u9ad8\u7ea7\u64cd\u4f5c\u653e\u5728\u53f3\u4fa7\u3002</p></div></div><div class="toolbar action-bar astr-actions desktop-action-grid"><div class="action-group"><span>\u670d\u52a1\u63a7\u5236</span>${btn("\u542f\u52a8","astrAct('start')","success")}${btn("\u505c\u6b62","astrAct('stop')","danger-soft")}${btn("\u91cd\u542f","astrAct('restart')","primary")}</div><div class="action-group"><span>\u7ef4\u62a4\u64cd\u4f5c</span>${btn("\u5237\u65b0\u72b6\u6001","refreshAstrbotPage()","")}${btn("\u514d@\u514d\u524d\u7f00","applyNoPrefix()","success")}${btn("\u4e00\u952e\u914d\u7f6e","repairConnection()","primary")}${btn("\u7f16\u8f91\u914d\u7f6e","editAstrConfig()","")}</div></div><h3>\u5bb9\u5668\u65e5\u5fd7</h3><pre id="astrLog" class="code">加载中...</pre></div><div class="card span12 plugin-card"><div class="section-head"><div><h3>AstrBot 插件</h3><p class="muted">上传插件 zip 后可一键安装并重启 AstrBot。</p></div><div class="plugin-path-badge" title="${q(pl.base)}"><span>插件目录</span><b>${safeText(pl.base)}</b></div></div><div class="toolbar plugin-toolbar"><button onclick="files()">上传插件 zip</button><button class="primary" onclick="astrAct('restart')">重启 AstrBot 生效</button></div><div class="file-cards plugin-list">${(pl.plugins||[]).map(x=>`<div class="file-card plugin-item"><div><b>${x.is_dir?"插件目录":"插件文件"} / ${safeText(x.name)}</b><div class="muted plugin-meta"><span title="${q(x.path)}">${safeText(x.path)}</span><em>${fmtBytes(x.size)} / ${safeText(x.mtime)}</em></div></div></div>`).join("")||"<div class='empty-state'>暂无插件</div>"}</div></div><div class="card span12"><h3>部署信息</h3><pre class="code">${esc(a.deploy_info)}</pre></div></section>`;loadLog("astrbot","#astrLog")}
function btn(t,js,c){return `<button class="${c||'soft'} pill-btn" onclick="${js}">${t}</button>`}
async function refreshAstrbotPage(){invalidateCache("astrbot","plugins:astrbot","dashboard");return astrbot()}
async function refreshNapcatPage(){invalidateCache("napcat","pool","dashboard");return napcat()}
async function liveRefreshCurrentPage(){try{clearOldNapPending();if(state.livePageRefreshing||state.busy||document.hidden||userEditingForm())return;if(!["napcat","pool"].includes(state.page))return;if(!$("#content"))return;if(!$("#modal")?.classList.contains("hidden"))return;const now=Date.now();if(now-state.livePageLast<1800)return;state.livePageRefreshing=true;state.livePageLast=now;invalidateCache("dashboard","napcat","pool");if(state.page==="pool")await pool();else if(state.page==="napcat")await napcat()}catch(e){console.debug(e)}finally{state.livePageRefreshing=false}}
async function astrAct(a){const run=()=>withBusy("AstrBot \u5904\u7406\u4e2d",async()=>{await req("/api/astrbot/action",{method:"POST",body:JSON.stringify({action:a})});toast("\u64cd\u4f5c\u5df2\u6267\u884c\uff0c\u6b63\u5728\u5237\u65b0\u72b6\u6001");setTimeout(()=>refresh(true,true),900)});if(["stop","restart"].includes(a))return confirmDanger({title:a==="restart"?"\u786e\u8ba4\u91cd\u542f AstrBot\uff1f":"\u786e\u8ba4\u505c\u6b62 AstrBot\uff1f",name:"AstrBot \u4e3b\u670d\u52a1",message:a==="restart"?"\u91cd\u542f\u671f\u95f4\u4e3b\u670d\u52a1\u4f1a\u77ed\u6682\u4e0d\u53ef\u7528\u3002":"\u505c\u6b62\u540e WebUI \u548c\u673a\u5668\u4eba\u54cd\u5e94\u53ef\u80fd\u4e2d\u65ad\u3002",confirmText:a==="restart"?"\u786e\u8ba4\u91cd\u542f":"\u786e\u8ba4\u505c\u6b62",onConfirm:run});return run()}
async function applyNoPrefix(){return withBusy("\u6b63\u5728\u5e94\u7528\u514d @ \u914d\u7f6e",async()=>{const t=await req("/api/astrbot/no-prefix",{method:"POST",body:"{}"});toast("\u4efb\u52a1\u5df2\u5f00\u59cb\uff0c\u6b63\u5728\u91cd\u542f AstrBot");showTask(t.id)})}
async function repairConnection(){return withBusy("\u6b63\u5728\u4e00\u952e\u914d\u7f6e\u8fde\u63a5",async()=>{const t=await req("/api/connection/repair",{method:"POST",body:"{}"});toast("\u4e00\u952e\u914d\u7f6e\u5df2\u5f00\u59cb\uff0c\u4f1a\u81ea\u52a8\u91cd\u542f\u9700\u8981\u5237\u65b0\u7684\u670d\u52a1");showTask(t.id);invalidateCache("dashboard","napcat","pool","astrbot");loadTasks()})}

function recoveryText(r={}){return {online:"\u5728\u7ebf",suspect:"\u7591\u4f3c\u5f02\u5e38",recovering:"\u81ea\u52a8\u6062\u590d\u4e2d",waiting_qr:"\u7b49\u5f85\u626b\u7801",limited:"\u6682\u505c\u6062\u590d"}[r.health]||"\u672a\u68c0\u6d4b"}
function recoveryBadge(r={}){let h=r.health||"unknown",c=h==="online"?"green":h==="limited"?"red":h==="recovering"?"blue":h==="suspect"?"orange":"grey";return `<span class="status-pill ${c}" title="${q(r.reason||'')}">${safeText(recoveryText(r))}</span>`}
function napActionLabel(action){return {add:"\u521b\u5efa\u4e2d",start:"\u542f\u52a8\u4e2d",stop:"\u505c\u6b62\u4e2d",restart:"\u91cd\u542f\u4e2d",restart_all:"\u91cd\u542f\u4e2d",delete:"\u5220\u9664\u4e2d"}[action]||"\u5904\u7406\u4e2d"}
function napIsPending(name){return !!state.napPending?.[String(name||"")]}
function napPendingClass(name){return napIsPending(name)?"nap-processing":""}
function napPendingBadge(name){const p=state.napPending?.[String(name||"")];return p?`<span class="status-pill blue nap-pending-badge"><span class="spin mini-spin"></span>${safeText(napActionLabel(p.action))}</span>`:""}
function setNapPending(name,action){const key=String(name||"");if(!key)return;state.napPending[key]={action,ts:Date.now()};document.querySelectorAll(`[data-nap-name="${CSS.escape(key)}"]`).forEach(el=>{el.classList.add("nap-processing");el.querySelectorAll(".nap-row-actions button,.action-pills button").forEach(b=>{b.disabled=true;b.setAttribute("aria-disabled","true")});let slot=el.querySelector(".nap-inline-pending");if(slot)slot.innerHTML=napPendingBadge(key)})}
function clearNapPending(name){const key=String(name||"");if(!key)return;delete state.napPending[key];document.querySelectorAll(`[data-nap-name="${CSS.escape(key)}"]`).forEach(el=>{el.classList.remove("nap-processing");el.querySelectorAll(".nap-row-actions button,.action-pills button").forEach(b=>{b.disabled=false;b.removeAttribute("aria-disabled")});let slot=el.querySelector(".nap-inline-pending");if(slot)slot.innerHTML=""})}
function clearOldNapPending(){const now=Date.now();Object.keys(state.napPending||{}).forEach(k=>{if(now-(state.napPending[k]?.ts||0)>180000)clearNapPending(k)})}
async function napcat(page="napcat",seq=state.renderSeq){
  const rows=await cachedReq("napcat","/api/napcat");
  if(!pageStillActive(page,seq))return;
  $("#content").innerHTML=`<section class="grid"><div class="card span12 nap-hero"><div class="nap-hero-main"><div class="nap-icon">${icon("nodes")}</div><div><h3>\u673a\u5668\u4eba\u7ba1\u7406</h3><p class="muted">\u5df2\u521b\u5efa ${rows.length} \u4e2a\u673a\u5668\u4eba\uff0c\u53ef\u4ee5\u5728\u8fd9\u91cc\u65b0\u589e\u3001\u626b\u7801\u3001\u91cd\u542f\u548c\u67e5\u770b\u65e5\u5fd7\u3002</p></div></div><div class="nap-create nap-create-card"><label>\u65b0\u589e\u6570\u91cf<input id="napCount" type="number" min="1" max="999" value="1"></label><button class="primary" onclick="napAdd()">\u521b\u5efa\u673a\u5668\u4eba</button><button class="soft" onclick="confirmDanger({title:'\u786e\u8ba4\u91cd\u542f\u5168\u90e8\u673a\u5668\u4eba\uff1f',name:'\u5168\u90e8 NapCat \u5b9e\u4f8b',message:'\u6240\u6709\u673a\u5668\u4eba\u4f1a\u4f9d\u6b21\u77ed\u6682\u79bb\u7ebf\uff0c\u8bf7\u786e\u8ba4\u5f53\u524d\u6ca1\u6709\u91cd\u8981\u64cd\u4f5c\u3002',confirmText:'\u786e\u8ba4\u91cd\u542f\u5168\u90e8',onConfirm:()=>napAct('restart_all')})">\u91cd\u542f\u5168\u90e8</button><button class="soft" onclick="refreshNapcatPage()">\u5237\u65b0\u72b6\u6001</button><button class="soft" onclick="repairConnection()">\u4e00\u952e\u914d\u7f6e</button></div></div><div class="card span12 nap-list-card">${tableNap(rows)}${mobileNap(rows)}</div>${taskPanel()}</section>`;
  loadTasks();
}
async function pool(page="pool",seq=state.renderSeq){
  const d=await cachedReq("pool","/api/napcat/pool");
  if(!pageStillActive(page,seq))return;
  const s=d.summary||{}, rows=d.items||[];
  $("#content").innerHTML=`<section class="grid pool-page">
    ${poolKpi("nodes","\u603b\u673a\u5668\u4eba",s.total||0,"i-blue")}
    ${poolKpi("bot","\u5df2\u767b\u5f55",s.online||0,"i-green")}
    ${poolKpi("dashboard","\u7a7a\u95f2",s.idle||0,"i-orange")}
    ${poolKpi("logs","\u5f85\u626b\u7801",s.assigned||0,"i-blue")}
    <div class="card span12 pool-hero"><div><h3>\u673a\u5668\u4eba\u6c60</h3><p class="muted">\u7edf\u4e00\u67e5\u770b\u673a\u5668\u4eba\u8d44\u6e90\uff1a\u8c01\u5728\u7ebf\u3001\u8c01\u7a7a\u95f2\u3001\u8c01\u6b63\u5728\u7b49\u5f85\u626b\u7801\u3002\u9002\u5408\u591a\u4eba\u7533\u8bf7\u767b\u5f55\u65f6\u7edf\u4e00\u7ba1\u7406\u3002</p></div><div class="pool-actions"><button class="primary" onclick="go('napcat')">\u521b\u5efa\u673a\u5668\u4eba</button><button class="soft" onclick="refreshPool()">\u5237\u65b0\u6c60\u72b6\u6001</button><button class="soft danger-text" onclick="cleanupIdlePool()">\u6e05\u7406\u7a7a\u95f2</button></div></div>
    <div class="card span12 pool-list-card">${poolTable(rows)}${poolMobile(rows)}</div>
    ${taskPanel()}
  </section>`;
  loadTasks();
}
function poolKpi(ic,label,value,cls){return `<div class="card span3 kpi pool-kpi"><div><div class="muted">${label}</div><strong>${safeText(value)}</strong></div><div class="icon ${cls}">${icon(ic)}</div></div>`}
function poolStateBadge(x){const m={online:["green","\u5df2\u767b\u5f55"],idle:["orange","\u7a7a\u95f2"],assigned:["blue","\u5f85\u626b\u7801"],abnormal:["red","\u9700\u5904\u7406"],stopped:["grey","\u5df2\u505c\u6b62"]};const v=m[x]||["grey",x||"\u672a\u77e5"];return `<span class="status-pill ${v[0]}">${safeText(v[1])}</span>`}
function poolWho(r){if(r.login_name||r.login_uin)return `${r.login_name||"QQ"}${r.login_uin?`\uff08${r.login_uin}\uff09`:""}`;if(r.assigned_to)return `\u7533\u8bf7\u4eba ${r.assigned_to}`;return "\u6682\u65e0"}
function poolTable(rows){return `<div class="table-wrap"><table class="table pool-table"><thead><tr><th>\u673a\u5668\u4eba</th><th>\u6c60\u72b6\u6001</th><th>\u767b\u5f55\u8d26\u53f7 / \u7533\u8bf7\u4eba</th><th>\u8fde\u63a5\u5065\u5eb7</th><th>\u7aef\u53e3</th><th>\u64cd\u4f5c</th></tr></thead><tbody>${rows.map(r=>`<tr data-nap-name="${q(r.name)}" class="${napPendingClass(r.name)}"><td><b>${safeText(r.display_name||botName(r.name))}</b><div class="compact-url">${safeText(r.name)}</div><div class="nap-inline-pending">${napPendingBadge(r.name)}</div></td><td>${poolStateBadge(r.pool_state)}</td><td><span class="pool-who">${safeText(poolWho(r))}</span>${r.assignment_ttl?`<div class="compact-url">\u5360\u7528\u5269\u4f59 ${r.assignment_ttl}s</div>`:""}</td><td>${statusBadge(r.status)} ${recoveryBadge(r.recovery||{})}<div class="compact-url">OneBot\uff1a${r.onebot_ok?"\u6b63\u5e38":"\u672a\u786e\u8ba4"}</div></td><td>${safeText(r.webui_port)} / ${safeText(r.ws_port)} / ${safeText(r.http_port)}</td><td><div class="actions action-pills nap-row-actions">${oneNapBtns(r)}</div></td></tr>`).join("")||`<tr><td colspan="6"><div class="empty-state">\u6682\u65e0\u673a\u5668\u4eba</div></td></tr>`}</tbody></table></div>`}
function poolMobile(rows){return `<div class="mobile-list pool-mobile-list">${rows.map(r=>`<div class="card pool-mobile-card ${napPendingClass(r.name)}" data-nap-name="${q(r.name)}"><div class="nap-card-top"><div><h3>${safeText(r.display_name||botName(r.name))}</h3><p class="compact-url">${safeText(r.name)}</p><div class="nap-inline-pending">${napPendingBadge(r.name)}</div></div>${poolStateBadge(r.pool_state)}</div><div class="pool-info-grid"><div><span>\u767b\u5f55/\u7533\u8bf7</span><b>${safeText(poolWho(r))}</b></div><div><span>\u5bb9\u5668</span><b>${safeText(statusText(r.status))}</b></div><div><span>\u6062\u590d</span><b>${safeText(recoveryText(r.recovery||{}))}</b></div><div><span>\u7aef\u53e3</span><b>${safeText(r.webui_port)} / ${safeText(r.http_port)}</b></div></div><a class="link-pill nap-webui-main" href="${safeHref(napLoginUrl(r))}" target="_blank" rel="noopener noreferrer">\u6253\u5f00 WebUI</a><div class="actions action-pills">${oneNapBtns(r)}</div></div>`).join("")||"<div class='card empty-state'>\u6682\u65e0\u673a\u5668\u4eba</div>"}</div>`}
async function refreshPool(){invalidateCache("dashboard","napcat","pool");return pool()}
async function cleanupIdlePool(){confirmDo("\u8f93\u5165 \u6e05\u7406\u7a7a\u95f2\u673a\u5668\u4eba \u786e\u8ba4\u5220\u9664\u6240\u6709\u7a7a\u95f2\u673a\u5668\u4eba\u3002\u9ed8\u8ba4\u4fdd\u7559\u6570\u636e\u76ee\u5f55\uff0c\u53ea\u5220\u9664\u5bb9\u5668\u548c\u7d22\u5f15\u3002","\u6e05\u7406\u7a7a\u95f2\u673a\u5668\u4eba",async()=>{const t=await req("/api/napcat/pool/cleanup",{method:"POST",body:JSON.stringify({confirm:"\u6e05\u7406\u7a7a\u95f2\u673a\u5668\u4eba",keep_data:true})});toast("\u6e05\u7406\u4efb\u52a1\u5df2\u5f00\u59cb");showTask(t.id)})}

function napLoginUrl(r){if(r.login_url)return String(r.login_url);return `${String(r.url).replace(/\/?$/ ,"")}?token=${encodeURIComponent(r.token)}`}
function tableNap(rows){return `<div class="table-wrap"><table class="table"><thead><tr><th>机器人</th><th>容器状态</th><th>恢复状态</th><th>WebUI 登录</th><th>端口</th><th>操作</th></tr></thead><tbody>${rows.map(r=>`<tr data-nap-name="${q(r.name)}" class="${napPendingClass(r.name)}"><td><b>${safeText(botName(r.name))}</b><div class="compact-url">内部容器：${safeText(r.name)}</div><div class="nap-inline-pending">${napPendingBadge(r.name)}</div></td><td>${statusBadge(r.status)}</td><td>${recoveryBadge(r.recovery||{})}<div class="compact-url">${safeText((r.recovery||{}).reason||"")}</div></td><td><a class="link-pill nap-webui-link" href="${safeHref(napLoginUrl(r))}" target="_blank" rel="noopener noreferrer">打开 ${safeText(botName(r.name))} WebUI</a></td><td>${safeText(r.webui_port)} / ${safeText(r.ws_port)} / ${safeText(r.http_port)}</td><td><div class="actions action-pills nap-row-actions">${oneNapBtns(r)}</div></td></tr>`).join("")||`<tr><td colspan="6"><div class="empty-state">暂无机器人</div></td></tr>`}</tbody></table></div>`}
function mobileNap(rows){return `<div class="mobile-list nap-mobile-list">${rows.map(r=>`<div class="card nap-mobile-card ${napPendingClass(r.name)}" data-nap-name="${q(r.name)}"><div class="nap-card-top"><div><h3>${safeText(botName(r.name))}</h3><p class="compact-url">内部容器：${safeText(r.name)}</p><div class="nap-inline-pending">${napPendingBadge(r.name)}</div></div>${statusBadge(r.status)}</div><div class="nap-mobile-status"><span>恢复状态</span>${recoveryBadge(r.recovery||{})}</div><a class="link-pill nap-webui-main" href="${safeHref(napLoginUrl(r))}" target="_blank" rel="noopener noreferrer">打开 WebUI</a><div class="actions action-pills">${oneNapBtns(r)}</div></div>`).join("")||"<div class='card empty-state'>暂无机器人</div>"}</div>`}
function okIcon(){return `<svg class="success-symbol" viewBox="0 0 72 72" fill="none" aria-hidden="true"><circle class="success-symbol-disc" cx="36" cy="36" r="32" fill="#34C759"/><path class="success-symbol-check" d="M20.5 36.8 31 47.2 52.5 25.8" stroke="#fff" stroke-width="5.8" stroke-linecap="round" stroke-linejoin="round"/></svg>`}
function qrIcon(){return `<svg class="qr-mini" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><path d="M4 4.8A.8.8 0 0 1 4.8 4h4.4a.8.8 0 0 1 .8.8v4.4a.8.8 0 0 1-.8.8H4.8A.8.8 0 0 1 4 9.2V4.8Z"/><path d="M14 4.8a.8.8 0 0 1 .8-.8h4.4a.8.8 0 0 1 .8.8v4.4a.8.8 0 0 1-.8.8h-4.4a.8.8 0 0 1-.8-.8V4.8Z"/><path d="M4 14.8a.8.8 0 0 1 .8-.8h4.4a.8.8 0 0 1 .8.8v4.4a.8.8 0 0 1-.8.8H4.8a.8.8 0 0 1-.8-.8v-4.4Z"/><path d="M14 14h2.5M19.5 14h.5M14 17h1M18 17h2M14 20h6M7 7h.01M17 7h.01M7 17h.01"/></svg>`}
function scanHeroIcon(){return `<svg class="scan-hero-icon" viewBox="0 0 64 64" fill="none" aria-hidden="true"><rect x="14" y="14" width="36" height="36" rx="12" stroke="currentColor" stroke-width="3" opacity=".16"/><path d="M18 27v-6a3 3 0 0 1 3-3h6M37 18h6a3 3 0 0 1 3 3v6M46 37v6a3 3 0 0 1-3 3h-6M27 46h-6a3 3 0 0 1-3-3v-6" stroke="currentColor" stroke-width="3.2" stroke-linecap="round"/><path d="M22 32h20" stroke="currentColor" stroke-width="3.2" stroke-linecap="round"/><path d="M27 27h10M27 37h10" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" opacity=".5"/></svg>`}
function oneNapBtns(r){const n=typeof r==="string"?r:r.name,u=typeof r==="string"?"":napLoginUrl(r),disabled=napIsPending(n)?' disabled aria-disabled="true"':"";return `<button class="tiny scan"${disabled} onclick="showQrLogin('${q(n)}','${q(u)}')">${qrIcon()}扫码</button><button class="tiny success"${disabled} onclick="napAct('start','${q(n)}')">启动</button><button class="tiny danger-soft"${disabled} onclick="confirmNapAction('stop','${q(n)}')">停止</button><button class="tiny primary"${disabled} onclick="confirmNapAction('restart','${q(n)}')">重启</button><button class="tiny"${disabled} onclick="showLog('${q(n)}')">日志</button><button class="tiny danger"${disabled} onclick="confirmNapAction('delete','${q(n)}')">删除</button>`}
async function showQrLogin(name,url){
  if(state.qrTimer){clearInterval(state.qrTimer);state.qrTimer=null}
  const title=`${botName(name)} 扫码登录`;
  openModal(`<div class="qr-login"><button class="qr-close" onclick="closeModal()" aria-label="\u5173\u95ed">&times;</button><div class="qr-login-head"><div class="scan-title-icon">${scanHeroIcon()}</div><div><h3>${safeText(title)}</h3><p class="muted">\u6b63\u5728\u5411 NapCat \u83b7\u53d6 QQ \u767b\u5f55\u4e8c\u7ef4\u7801...</p></div></div><div id="qrLoginBody" class="qr-login-body"><div class="qr-skeleton"></div></div><div class="qr-status muted" id="qrLoginStatus">\u51c6\u5907\u4e2d</div><div class="toolbar scan-actions"><button class="primary" onclick="refreshNapQr('${q(name)}')">\u5237\u65b0\u4e8c\u7ef4\u7801</button><a class="link-pill" href="${safeHref(url)}" target="_blank" rel="noopener noreferrer">\u6253\u5f00 NapCat WebUI</a></div></div>`,null);
  await loadNapQr(name);
  state.qrTimer=setInterval(()=>pollNapQr(name),3000);
}
function showAlreadyLogin(name, info={}){
  const nick=info.nick||info.nickname||info.uin||"QQ 已登录";
  const html=`<div class="already-modal"><div class="ok-doodle big">${okIcon()}</div><h3>已经登录</h3><p>${safeText(botName(name))} 当前已经连接 QQ，不需要重复扫码。</p><div class="already-meta">${safeText(nick)}</div><button class="primary wide" onclick="closeModal()">知道了</button></div>`;
  openModal(html,null);
  setTimeout(()=>{if(!$("#modal")?.classList.contains("hidden"))closeModal()},1600);
}

async function loadNapQr(name){
  const box=$("#qrLoginBody"),st=$("#qrLoginStatus");
  try{
    const d=await req("/api/napcat/qq-login",{method:"POST",body:JSON.stringify({name,action:"qrcode"})});
    if(d.already_login){
      const info=d.login_info||{}, nick=info.nick||info.nickname||info.uin||"QQ 已登录";
      if(box)box.innerHTML=`<div class="login-ok-card"><div class="ok-doodle">${okIcon()}</div><h3>已经登录</h3><p>${safeText(botName(name))} 当前已连接 QQ，无需再次扫码。</p><div class="compact-url">${safeText(nick)}</div></div>`;
      if(st)st.textContent="机器人在线，可以直接使用，窗口即将关闭";
      setTimeout(()=>closeModal(),1200);
      return;
    }
    if(box)box.innerHTML=`<div class="qr-card"><div class="qr-svg">${d.svg}</div></div><div class="qr-help">请用手机 QQ 扫描二维码登录</div>`;
    if(st)st.textContent="等待扫码确认";
  }catch(e){
    if(box)box.innerHTML=`<div class="qr-error">${safeText(e.message||e)}</div>`;
    if(st)st.textContent="获取失败，可以点刷新二维码再试";
  }
}
async function refreshNapQr(name){
  const st=$("#qrLoginStatus"); if(st)st.textContent="正在刷新二维码...";
  await req("/api/napcat/qq-login",{method:"POST",body:JSON.stringify({name,action:"refresh"})}).catch(()=>{});
  setTimeout(()=>loadNapQr(name),900);
}
async function pollNapQr(name){
  if($("#modal")?.classList.contains("hidden")){clearInterval(state.qrTimer);state.qrTimer=null;return}
  try{
    const r=await req("/api/napcat/qq-login",{method:"POST",body:JSON.stringify({name,action:"status"})});
    const data=r.data||{}; const st=$("#qrLoginStatus");
    if(data.isLogin){
      const box=$("#qrLoginBody"),info=data.loginInfo||{},nick=info.nick||info.nickname||info.uin||"QQ 已登录";
      if(box)box.innerHTML=`<div class="login-ok-card"><div class="ok-doodle">${okIcon()}</div><h3>登录成功</h3><p>${safeText(botName(name))} 已经连接 QQ。</p><div class="compact-url">${safeText(nick)}</div></div>`;
      if(st)st.textContent="机器人在线，可以直接使用，窗口即将关闭";
      toast("QQ 登录成功");
      clearInterval(state.qrTimer);state.qrTimer=null;
      invalidateCache("dashboard","napcat","pool");setTimeout(()=>{closeModal();refresh(true,true)},450);setTimeout(()=>{invalidateCache("dashboard","napcat","pool");refresh(state.page==="napcat"||state.page==="pool",true)},1800);
      return
    }
    if(data.isOffline){if(st)st.textContent="账号离线，请重新扫码";return}
    if(data.loginError){if(st)st.textContent=data.loginError}
  }catch(e){}
}
async function napAdd(){return withBusy("\u6b63\u5728\u521b\u5efa\u673a\u5668\u4eba",async()=>{const count=Number($("#napCount").value||1);if(!Number.isInteger(count)||count<1||count>999)return toast("\u6570\u91cf\u5fc5\u987b\u662f 1-999");const t=await req("/api/napcat/action",{method:"POST",body:JSON.stringify({action:"add",count})});toast("\u521b\u5efa\u4efb\u52a1\u5df2\u5f00\u59cb\uff0c\u4e0b\u9762\u4f1a\u663e\u793a\u8fdb\u5ea6");showTask(t.id);loadTasks()})}
function confirmNapAction(action,name){const display=botName(name);const map={restart:["\u786e\u8ba4\u91cd\u542f\u5b9e\u4f8b\uff1f","\u91cd\u542f\u671f\u95f4\u673a\u5668\u4eba\u53ef\u80fd\u6682\u65f6\u79bb\u7ebf\u3002","\u786e\u8ba4\u91cd\u542f"],stop:["\u786e\u8ba4\u505c\u6b62\u5b9e\u4f8b\uff1f","\u505c\u6b62\u540e\u8be5\u673a\u5668\u4eba\u5c06\u4e0d\u518d\u54cd\u5e94\uff0c\u76f4\u5230\u91cd\u65b0\u542f\u52a8\u3002","\u786e\u8ba4\u505c\u6b62"],delete:["\u786e\u8ba4\u5220\u9664\u5b9e\u4f8b\uff1f","\u9ed8\u8ba4\u4fdd\u7559\u6570\u636e\u76ee\u5f55\uff0c\u53ea\u5220\u9664\u5bb9\u5668\u548c\u7d22\u5f15\u8bb0\u5f55\u3002","\u786e\u8ba4\u5220\u9664"]};const m=map[action]||["\u786e\u8ba4\u6267\u884c\u64cd\u4f5c\uff1f","\u8be5\u64cd\u4f5c\u4f1a\u63d0\u4ea4\u5230\u670d\u52a1\u5668\u6267\u884c\u3002","\u786e\u8ba4"];return confirmDanger({title:m[0],name:display,message:m[1],confirmText:m[2],onConfirm:()=>napAct(action,name,action==="delete"?{confirm:name,keep_data:true}:{})})}
function markNapDeleting(name){try{setNapPending(name,"delete");const key=String(name||"");document.querySelectorAll("[data-nap-name]").forEach(el=>{if(el.getAttribute("data-nap-name")===key){el.classList.add("nap-removing");setTimeout(()=>el.remove(),160)}});toast("\u5220\u9664\u4efb\u52a1\u5df2\u5f00\u59cb")}catch(e){console.debug(e)}}
async function napAct(action,name,extra={}){return withBusy(action==="delete"?"\u6b63\u5728\u5220\u9664\u673a\u5668\u4eba":"\u673a\u5668\u4eba\u5904\u7406\u4e2d",async()=>{if(action!=="restart_all"&&name)setNapPending(name,action);const res=await req("/api/napcat/action",{method:"POST",body:JSON.stringify(Object.assign({action,name},extra))});if(res&&res.id){invalidateCache("dashboard","napcat","pool","astrbot");if(action==="delete")markNapDeleting(name);else toast("\u4efb\u52a1\u5df2\u521b\u5efa\uff0c\u6b63\u5728\u7b49\u5f85\u670d\u52a1\u5668\u5b8c\u6210");showTask(res.id);loadTasks();return}toast("\u64cd\u4f5c\u5df2\u6267\u884c\uff0c\u6b63\u5728\u5237\u65b0");invalidateCache("dashboard","napcat","pool","astrbot");await refresh(true,true);if(state.page==="napcat")napcat();if(name)clearNapPending(name)})}

function showLog(n){state.page="logs";location.hash="logs";++state.renderSeq;renderNav();logs(n)}
function logs(initial="astrbot"){
  $("#content").innerHTML=`<section class="grid"><div class="card span12 log-center-card"><div class="section-head"><div><h3>\u65e5\u5fd7\u4e2d\u5fc3</h3><p class="muted">\u5b9e\u65f6\u65e5\u5fd7\u4f7f\u7528 SSE \u957f\u8fde\u63a5\uff0c\u652f\u6301\u6682\u505c\u6eda\u52a8\u548c\u65ad\u7ebf\u81ea\u52a8\u6062\u590d\u3002</p></div></div><div class="log-toolbar"><div class="log-filters"><select id="logTarget"><option value="astrbot">AstrBot \u4e3b\u670d\u52a1</option><option value="deploy">\u90e8\u7f72\u811a\u672c</option><option value="panel">Web \u9762\u677f</option>${(state.data?.napcats||[]).map(n=>`<option value="${q(n.name)}">${safeText(botName(n.name))}</option>`).join("")}</select><input id="logKey" placeholder="\u5173\u952e\u8bcd\u8fc7\u6ee4\uff0c\u4f8b\u5982 error"></div><div class="log-actions"><button class="primary pill-btn" onclick="loadLog()">\u5237\u65b0\u4e00\u6b21</button><button id="liveBtn" class="soft pill-btn" onclick="toggleLiveLog()">\u5173\u95ed\u5b9e\u65f6</button><button id="pauseLogBtn" class="soft pill-btn" onclick="toggleLogPause()">\u6682\u505c\u6eda\u52a8</button><button class="soft pill-btn" onclick="fullLog()">\u5168\u5c4f\u67e5\u770b</button></div></div><pre id="logBox" class="code log-viewer">\u52a0\u8f7d\u4e2d...</pre></div></section>`;
  $("#logTarget").value=initial;$("#logTarget").onchange=()=>{loadLog();startLiveLog(true)};$("#logKey").oninput=()=>{startLiveLog(true)};state.logPaused=false;loadLog();startLiveLog(true)
}
async function loadLog(target,sel){target=target||$("#logTarget")?.value||"astrbot";let key=$("#logKey")?.value||"";const d=await req(`/api/logs?target=${encodeURIComponent(target)}&keyword=${encodeURIComponent(key)}&lines=500`);renderLogContent(d.content,sel||"#logBox")}
function renderLogContent(content,sel="#logBox"){const box=$(sel);if(!box)return;let html=esc(content).replace(/(error|fail|exception|traceback|\u5931\u8d25|\u9519\u8bef|\u5f02\u5e38)/ig,'<span class="err">$1</span>');const nearBottom=box.scrollHeight-box.scrollTop-box.clientHeight<80;box.innerHTML=html;if(!state.logPaused&&(nearBottom||sel!=="#logBox"))box.scrollTop=box.scrollHeight}
function fullLog(){$("#logBox").requestFullscreen?.()}
function closeLiveLog(){if(state.logStream){state.logStream.close();state.logStream=null}$("#liveBtn")?.classList.remove("live-on")}
function startLiveLog(force=false){if(state.page!=="logs")return;if(state.logStream&&force)closeLiveLog();if(state.logStream)return;let target=$("#logTarget")?.value||"astrbot",key=$("#logKey")?.value||"";state.logStream=new EventSource(`/api/logs/stream?target=${encodeURIComponent(target)}&keyword=${encodeURIComponent(key)}`);$("#liveBtn")?.classList.add("live-on");if($("#liveBtn"))$("#liveBtn").textContent="\u5173\u95ed\u5b9e\u65f6";state.logStream.onmessage=e=>{let d=JSON.parse(e.data);renderLogContent(d.content)};state.logStream.onerror=()=>{closeLiveLog();if(state.page==="logs")setTimeout(()=>startLiveLog(false),2500)}}
function toggleLiveLog(){if(state.logStream){closeLiveLog();if($("#liveBtn"))$("#liveBtn").textContent="\u5f00\u542f\u5b9e\u65f6";toast("\u5b9e\u65f6\u65e5\u5fd7\u5df2\u5173\u95ed");return}startLiveLog(true);toast("\u5b9e\u65f6\u65e5\u5fd7\u5df2\u5f00\u542f")}
function toggleLogPause(){state.logPaused=!state.logPaused;const b=$("#pauseLogBtn");if(b)b.textContent=state.logPaused?"\u7ee7\u7eed\u6eda\u52a8":"\u6682\u505c\u6eda\u52a8";toast(state.logPaused?"\u5df2\u6682\u505c\u81ea\u52a8\u6eda\u52a8":"\u5df2\u6062\u590d\u81ea\u52a8\u6eda\u52a8")}
async function editAstrConfig(){const d=await req("/api/config/astrbot");openModal(`<h3>AstrBot JSON 配置编辑器</h3><p class="muted">${safeText(d.path)}</p><textarea id="cfgEdit" class="editor">${esc(d.content)}</textarea><label style="margin-top:10px"><input id="cfgRestart" type="checkbox" style="width:auto;min-height:auto"> 保存后重启 AstrBot</label>`,async()=>{let content=$("#cfgEdit").value;try{JSON.parse(content)}catch(e){return toast("JSON 格式错误："+e.message)}await req("/api/config/astrbot",{method:"POST",body:JSON.stringify({content,restart:$("#cfgRestart").checked})});closeModal();toast("配置已保存")})}
let fileCenterRows=[];
const FC={title:"\uD83D\uDCC1 \u6587\u4EF6\u4E2D\u5FC3",sub:"\u7EDF\u4E00\u7BA1\u7406\u56FE\u7247\u3001\u89C6\u9891\u3001\u63D2\u4EF6\u3001\u65E5\u5FD7\u3001\u5907\u4EFD\u7B49\u6240\u6709\u6587\u4EF6\u3002\u7F51\u9875\u3001AstrBot \u63D2\u4EF6\u3001API \u90FD\u5171\u7528\u8FD9\u4E00\u5957\u6587\u4EF6\u670D\u52A1\u3002",upload:"\u4E0A\u4F20\u6587\u4EF6",choose:"\u9009\u62E9\u6587\u4EF6",search:"\u641C\u7D22\u6587\u4EF6 / \u7C7B\u578B / MIME",empty:"\u6682\u65E0\u6587\u4EF6\uFF0C\u62D6\u62FD\u6216\u70B9\u51FB\u4E0A\u4F20\u5373\u53EF\u5F00\u59CB\u3002"};
function fileTypeLabel(f){const k=f.kind||"file";return ({image:"\u56FE\u7247",video:"\u89C6\u9891",audio:"\u97F3\u9891",pdf:"PDF",json:"JSON",text:"\u6587\u672C",archive:"\u538B\u7F29\u5305",file:"\u6587\u4EF6"})[k]||"\u6587\u4EF6"}
function fileGlyph(f){const k=f.kind||"file";return ({image:"IMG",video:"VID",audio:"AUD",pdf:"PDF",json:"JSN",text:"TXT",archive:"ZIP",file:"FILE"})[k]||"FILE"}
function fileRelativeTime(t){try{const d=new Date(String(t||"").replace(" ","T"));const diff=(Date.now()-d.getTime())/1000;if(!isFinite(diff))return safeText(t);if(diff<60)return "\u521A\u521A";if(diff<3600)return Math.floor(diff/60)+" \u5206\u949F\u524D";if(diff<86400)return Math.floor(diff/3600)+" \u5C0F\u65F6\u524D";if(diff<172800)return "\u6628\u5929";return String(t||"").slice(0,10)}catch{return safeText(t)}}
function selectedFileIds(){return [...document.querySelectorAll('.file-check:checked')].map(x=>x.value)}
async function files(page="files",seq=state.renderSeq){const d=await cachedReq("files","/api/files");if(!pageStillActive(page,seq))return;fileCenterRows=d.files||[];const st=d.statistics||{},sp=d.storage||{};$("#content").innerHTML=`<section class="grid file-center"><div class="card span12 page-head file-hero"><div><h3>${FC.title}</h3><p class="muted">${FC.sub}</p></div><div class="head-actions"><button class="soft" onclick="loadFileTokens()">API Token</button><button class="primary" onclick="document.querySelector('#uploadInput')?.click()">${FC.upload}</button></div></div><div class="card span3 kpi"><div><span>\u6587\u4EF6\u6570\u91CF</span><b>${st.count||0}</b></div><div class="icon">${icon("files")}</div></div><div class="card span3 kpi"><div><span>\u5DF2\u5360\u7A7A\u95F4</span><b>${fmtBytes(st.used||0)}</b></div><div class="icon">${icon("disk")}</div></div><div class="card span3 kpi"><div><span>\u4ECA\u65E5\u4E0A\u4F20</span><b>${st.today_uploads||0}</b></div><div class="icon">${icon("upload")}</div></div><div class="card span3 kpi"><div><span>\u5269\u4F59\u7A7A\u95F4</span><b>${fmtBytes(sp.remaining||sp.free||0)}</b></div><div class="icon">${icon("archive")}</div></div><div class="card span12 upload-card"><div id="drop" class="drop file-drop"><div class="drop-zone-inner"><div class="drop-title">\u70B9\u51FB\u4E0A\u4F20 / \u62D6\u62FD\u4E0A\u4F20</div><div class="drop-desc">\u652F\u6301\u56FE\u7247\u3001\u89C6\u9891\u3001\u97F3\u9891\u3001ZIP\u3001TXT\u3001JSON\u3001PDF\u3001Word\u3001Excel\u3001\u65E5\u5FD7\u3001\u5907\u4EFD\u7B49\u4EFB\u610F\u6587\u4EF6\uFF1B\u652F\u6301\u6D4F\u89C8\u5668\u3001AstrBot \u63D2\u4EF6\u3001Python\u3001Node\u3001curl \u8C03\u7528\u3002</div><input id="uploadInput" class="file-input-native" type="file" multiple><div class="file-pick-row"><label for="uploadInput" class="file-pick-btn">${FC.choose}</label><span id="filePickName" class="file-pick-name">\u624B\u673A\u7AEF\u53EF\u76F4\u63A5\u9009\u62E9\u6587\u4EF6</span></div><div id="uploadProgress" class="upload-progress hidden"><span></span></div></div></div></div><div class="card span12 file-toolbar-card"><div class="file-toolbar"><input id="fileSearch" class="file-search" placeholder="${FC.search}"><div class="file-bulk"><button class="tiny" onclick="copySelectedLinks()">\u6279\u91CF\u590D\u5236\u94FE\u63A5</button><button class="tiny" onclick="downloadSelectedFiles()">\u6279\u91CF\u4E0B\u8F7D</button><button class="tiny danger" onclick="deleteSelectedFiles()">\u6279\u91CF\u5220\u9664</button></div></div></div><div class="card span12 file-list-card"><div class="file-table-head"><span><input type="checkbox" onchange="document.querySelectorAll('.file-check').forEach(x=>x.checked=this.checked)"></span><span>\u6587\u4EF6</span><span>\u7C7B\u578B</span><span>\u5927\u5C0F</span><span>\u4E0A\u4F20\u65F6\u95F4</span><span>\u4E0B\u8F7D / \u8BBF\u95EE</span><span>\u5916\u94FE</span><span>\u64CD\u4F5C</span></div><div id="fileRows" class="file-table"></div></div><div id="fileTokenCard" class="card span12 hidden"></div><div class="card span12"><h3>\u670D\u52A1\u5668\u6587\u4EF6\u6D4F\u89C8</h3><p class="muted">\u4FDD\u7559\u539F\u6709\u7EF4\u62A4\u80FD\u529B\uFF0C\u4EC5\u4F9B\u7BA1\u7406\u5458\u67E5\u770B\u670D\u52A1\u5668\u5141\u8BB8\u8303\u56F4\u5185\u7684\u6587\u4EF6\u3002</p><div class="toolbar"><button onclick="serverFiles('/')">\u6D4F\u89C8\u670D\u52A1\u5668\u6587\u4EF6</button></div><pre id="filePreview" class="code">\u9009\u62E9\u6587\u4EF6\u9884\u89C8\uFF0C\u6216\u70B9\u51FB\u201C\u6D4F\u89C8\u670D\u52A1\u5668\u6587\u4EF6\u201D\u3002</pre></div></section>`;renderFileRows(fileCenterRows);bindFileUpload();$("#fileSearch").oninput=e=>{const q=e.target.value.toLowerCase().trim();renderFileRows(fileCenterRows.filter(f=>!q||String(f.filename||f.name||"").toLowerCase().includes(q)||String(f.mime||f.type||"").toLowerCase().includes(q)||String(f.kind||"").toLowerCase().includes(q)))} }
function renderFileRows(rows){const box=$("#fileRows");if(!box)return;box.innerHTML=(rows||[]).map(f=>`<div class="file-row"><span><input class="file-check" type="checkbox" value="${q(f.id)}"></span><span class="file-name-cell"><b class="file-glyph ${q(f.kind||'file')}">${safeText(fileGlyph(f))}</b><em title="${q(f.filename||f.name)}">${safeText(f.filename||f.name)}</em></span><span>${safeText(fileTypeLabel(f))}</span><span>${fmtBytes(f.size||0)}</span><span>${safeText(fileRelativeTime(f.created_at||f.updated_at))}</span><span>${Number(f.downloads||0)} / ${Number(f.views||0)}</span><span><button class="tiny" onclick="copyFileLink('${q(f.url)}')">\u590D\u5236\u5916\u94FE</button></span><span class="actions"><button class="tiny" onclick="previewFile('${q(f.id)}')">\u9884\u89C8</button><button class="tiny" onclick="location.href='/api/files/${encodeURIComponent(f.id)}/download'">\u4E0B\u8F7D</button><button class="tiny danger" onclick="confirmDeleteFile('${q(f.id)}','${q(f.filename||f.name)}')">\u5220\u9664</button></span></div>`).join("")||`<div class='empty-state'>${FC.empty}</div>`}
function bindFileUpload(){const input=$("#uploadInput"),drop=$("#drop");if(!input||!drop)return;input.onchange=e=>{const list=[...e.target.files];$("#filePickName").textContent=list.length?list.map(x=>x.name).join("\u3001"):"\u624B\u673A\u7AEF\u53EF\u76F4\u63A5\u9009\u62E9\u6587\u4EF6";upload(e.target.files)};drop.ondragover=e=>{e.preventDefault();drop.classList.add("active")};drop.ondragleave=()=>drop.classList.remove("active");drop.ondrop=e=>{e.preventDefault();drop.classList.remove("active");upload(e.dataTransfer.files)}}
async function upload(fileList){const files=[...fileList];if(!files.length)return;let fd=new FormData();files.forEach(f=>fd.append("files",f));const bar=$("#uploadProgress");bar?.classList.remove("hidden");if(bar)bar.querySelector("span").style.width="0%";await new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest();xhr.open("POST","/api/files/upload");xhr.upload.onprogress=e=>{if(e.lengthComputable&&bar)bar.querySelector("span").style.width=Math.round(e.loaded/e.total*100)+"%"};xhr.onload=()=>{try{const j=JSON.parse(xhr.responseText||"{}");if(xhr.status>=200&&xhr.status<300&&j.ok)resolve(j);else reject(new Error(j.message||"\u4E0A\u4F20\u5931\u8D25"))}catch(e){reject(e)}};xhr.onerror=()=>reject(new Error("\u4E0A\u4F20\u5931\u8D25"));xhr.send(fd)}).catch(e=>{toast(e.message);throw e});toast("\u4E0A\u4F20\u6210\u529F");await files()}
async function previewFile(id){const d=await req(`/api/files/${encodeURIComponent(id)}/preview`);let body="";if(d.preview_kind==="image")body=`<img class="file-preview-media" src="${safeHref(d.url)}" alt="${q(d.filename)}">`;else if(d.preview_kind==="video")body=`<video class="file-preview-media" controls src="${safeHref(d.url)}"></video>`;else if(d.preview_kind==="audio")body=`<audio controls src="${safeHref(d.url)}" style="width:100%"></audio>`;else if(d.preview_kind==="pdf")body=`<iframe class="file-preview-frame" src="${safeHref(d.url)}"></iframe>`;else if(d.preview_kind==="json")body=`<pre class="code selectable">${esc(JSON.stringify(d.json??JSON.parse(d.content||"null"),null,2))}</pre>`;else if(d.preview_kind==="text")body=`<pre class="code selectable">${esc(d.content||"")}</pre>`;else if(d.zip)body=`<pre class="code selectable">${esc(JSON.stringify(d.zip,null,2))}</pre>`;else body=`<div class="empty-state">\u8BE5\u7C7B\u578B\u6682\u4E0D\u652F\u6301\u5728\u7EBF\u9884\u89C8\uFF0C\u53EF\u76F4\u63A5\u4E0B\u8F7D\u67E5\u770B\u3002</div>`;openModal(`<div class="file-preview"><h3>${safeText(d.filename)}</h3><p class="muted">${safeText(d.mime)} / ${fmtBytes(d.size||0)}</p>${body}</div>`,null)}
async function copyFileLink(url){await copyText(url)}
function confirmDeleteFile(id,name){confirmDanger({title:"\u786E\u5B9A\u5220\u9664\uFF1F",name,message:"\u5220\u9664\u4EE5\u540E\u65E0\u6CD5\u6062\u590D\u3002",confirmText:"\u5220\u9664",onConfirm:()=>deleteFileById(id)})}
async function deleteFileById(id){await req(`/api/files/${encodeURIComponent(id)}/delete`,{method:"POST",body:JSON.stringify({confirm:id})});toast("\u5DF2\u5220\u9664");await files()}
async function deleteSelectedFiles(){const ids=selectedFileIds();if(!ids.length)return toast("\u8BF7\u9009\u62E9\u6587\u4EF6");confirmDanger({title:"\u6279\u91CF\u5220\u9664\uFF1F",name:`${ids.length} \u4E2A\u6587\u4EF6`,message:"\u5220\u9664\u4EE5\u540E\u65E0\u6CD5\u6062\u590D\u3002",confirmText:"\u6279\u91CF\u5220\u9664",onConfirm:async()=>{for(const id of ids)await req(`/api/files/${encodeURIComponent(id)}/delete`,{method:"POST",body:JSON.stringify({confirm:id})});toast("\u5DF2\u5220\u9664");await files()}})}
async function copySelectedLinks(){const ids=selectedFileIds();if(!ids.length)return toast("\u8BF7\u9009\u62E9\u6587\u4EF6");const links=fileCenterRows.filter(f=>ids.includes(String(f.id))).map(f=>f.url).join("\n");await copyText(links)}
function downloadSelectedFiles(){const ids=selectedFileIds();if(!ids.length)return toast("\u8BF7\u9009\u62E9\u6587\u4EF6");ids.forEach((id,i)=>setTimeout(()=>{location.href=`/api/files/${encodeURIComponent(id)}/download`},i*350))}
async function loadFileTokens(){const d=await req("/api/files/tokens");const card=$("#fileTokenCard");card.classList.remove("hidden");card.innerHTML=`<div class="section-head"><div><h3>API Token</h3><p class="muted">AstrBot \u63D2\u4EF6\u53EF\u7528 Authorization: Bearer token \u4E0A\u4F20\u6587\u4EF6\uFF0C\u65E0\u9700\u767B\u5F55\u540E\u53F0\u3002</p></div><button class="primary" onclick="createFileToken()">\u751F\u6210 Token</button></div><div class="file-cards">${(d.tokens||[]).map(t=>`<div class="file-card"><div><b>${safeText(t.name||'API Token')}</b><div class="muted token-meta"><span>\u521B\u5EFA\uFF1A${safeText(t.created_at||'')}</span><span>\u5C3E\u53F7\uFF1A****${safeText(t.last4||'')}</span><span>\u72B6\u6001\uFF1A${t.disabled?'\u5DF2\u7981\u7528':'\u53EF\u7528'}</span></div></div><div class="actions"><button class="tiny" onclick="toggleFileToken('${q(t.id)}',${!t.disabled})">${t.disabled?'\u542F\u7528':'\u7981\u7528'}</button><button class="tiny primary" onclick="regenFileToken('${q(t.id)}')">\u91CD\u65B0\u751F\u6210</button><button class="tiny danger" onclick="deleteFileToken('${q(t.id)}')">\u5220\u9664</button></div></div>`).join("")||"<div class='empty-state'>\u8FD8\u6CA1\u6709 API Token\u3002</div>"}</div>`;card.scrollIntoView({behavior:"smooth",block:"nearest"})}
async function createFileToken(){const d=await req("/api/files/tokens",{method:"POST",body:JSON.stringify({action:"create",name:"AstrBot Plugin"})});await copyText(d.token);toast("Token \u5DF2\u751F\u6210\u5E76\u590D\u5236\uFF0C\u8BF7\u4FDD\u5B58");loadFileTokens()}
async function regenFileToken(id){const d=await req("/api/files/tokens",{method:"POST",body:JSON.stringify({action:"regenerate",id})});await copyText(d.token);toast("\u65B0 Token \u5DF2\u590D\u5236\uFF0C\u8BF7\u4FDD\u5B58");loadFileTokens()}
async function toggleFileToken(id,disable){await req("/api/files/tokens",{method:"POST",body:JSON.stringify({action:disable?"disable":"enable",id})});toast("\u5DF2\u66F4\u65B0 Token");loadFileTokens()}
async function deleteFileToken(id){confirmDanger({title:"\u5220\u9664 API Token\uFF1F",message:"\u5220\u9664\u540E\u63D2\u4EF6\u5C06\u65E0\u6CD5\u7EE7\u7EED\u4F7F\u7528\u8BE5 Token \u4E0A\u4F20\u3002",confirmText:"\u5220\u9664",onConfirm:async()=>{await req("/api/files/tokens",{method:"POST",body:JSON.stringify({action:"delete",id})});toast("\u5DF2\u5220\u9664 Token");loadFileTokens()}})}
async function viewFile(p){const d=await req(`/api/files/view?path=${encodeURIComponent(p)}`);$("#filePreview").textContent=d.json?JSON.stringify(d.json,null,2):d.content}
async function applyAstr(p){await req("/api/files/apply",{method:"POST",body:JSON.stringify({path:p,kind:"astrbot_config"})});toast("\u5DF2\u5E94\u7528\u914D\u7F6E")}
async function applyPlugin(p){const t=await req("/api/files/apply",{method:"POST",body:JSON.stringify({path:p,kind:"astrbot_plugin",restart:true})});toast("\u63D2\u4EF6\u5B89\u88C5\u4EFB\u52A1\u5DF2\u521B\u5EFA");showTask(t.id)}
async function deleteFile(p){await req("/api/files/delete",{method:"POST",body:JSON.stringify({path:p,confirm:p})});toast("\u5DF2\u5220\u9664");files()}
async function serverFiles(path="/"){const d=await req(`/api/server-files?path=${encodeURIComponent(path)}`);$("#filePreview").outerHTML=`<div id="filePreview" class="server-browser"><div class="server-head"><button class="tiny" onclick="serverFiles('${q(d.parent)}')">\u8FD4\u56DE\u4E0A\u7EA7</button><span class="compact-url">${safeText(d.path)}</span></div><div class="file-cards">${d.items.map(x=>`<div class="file-card"><div><b>${x.is_dir?'\u76EE\u5F55':'\u6587\u4EF6'} / ${safeText(x.name)}</b><div class="muted">${safeText(x.path)}<br>${x.is_dir?"":fmtBytes(x.size)+" / "}${safeText(x.mtime)}</div></div><div class="actions">${x.is_dir?`<button class="tiny primary" onclick="serverFiles('${q(x.path)}')">\u6253\u5F00</button>`:`<button class="tiny" onclick="viewServerFile('${q(x.path)}')">\u9884\u89C8</button><button class="tiny" onclick="location.href='/api/server-files/download?path=${encodeURIComponent(x.path)}'">\u4E0B\u8F7D</button>`}</div></div>`).join("")||"\u7A7A\u76EE\u5F55"}</div></div>`}
async function viewServerFile(p){const d=await req(`/api/server-files/view?path=${encodeURIComponent(p)}`);$("#filePreview").outerHTML=`<pre id="filePreview" class="code">${esc(d.json?JSON.stringify(d.json,null,2):d.content)}</pre>`}
async function backup(page="backup",seq=state.renderSeq){const rows=await cachedReq("backup","/api/backups");if(!pageStillActive(page,seq))return;$("#content").innerHTML=`<section class="grid"><div class="card span12 page-head"><div><h3>\u5907\u4efd\u4e0e\u6062\u590d</h3><p class="muted">\u5907\u4efd AstrBot \u4e0e\u673a\u5668\u4eba\u6570\u636e\uff0c\u6062\u590d\u524d\u4f1a\u8981\u6c42\u4e8c\u6b21\u786e\u8ba4\u3002</p></div><div class="head-actions"><button class="primary" onclick="backupNow()">\u7acb\u5373\u5907\u4efd</button><button class="soft" onclick="files()">\u4e0a\u4f20\u5907\u4efd</button></div></div><div class="card span12"><div class="file-cards">${rows.map(b=>`<div class="file-card"><div><b>${safeText(b.name)}</b><div class="muted">${fmtBytes(b.size)} ? ${b.mtime}</div></div><div class="actions"><button class="tiny" onclick="location.href='/api/backups/download?file=${encodeURIComponent(b.name)}'">\u4e0b\u8f7d</button><button class="tiny danger" onclick="confirmDo('\u8f93\u5165 RESTORE \u786e\u8ba4\u6062\u590d','RESTORE',()=>restoreBackup('${q(b.name)}'))">\u6062\u590d</button></div></div>`).join("")||"<div class='empty-state'>\u6682\u65e0\u5907\u4efd</div>"}</div></div>${taskPanel()}</section>`}
async function backupNow(){return withBusy("\u6b63\u5728\u521b\u5efa\u5907\u4efd",async()=>{const t=await req("/api/backup/create",{method:"POST",body:"{}"});toast("\u5907\u4efd\u4efb\u52a1\u5df2\u521b\u5efa");showTask(t.id)})}
async function restoreBackup(f){return withBusy("\u6b63\u5728\u6062\u590d\u5907\u4efd",async()=>{const t=await req("/api/backup/restore",{method:"POST",body:JSON.stringify({file:f,confirm:"RESTORE"})});showTask(t.id)})}
function update(){$("#content").innerHTML=`<section class="grid"><div class="card span12 page-head"><div><h3>\u66f4\u65b0\u4e2d\u5fc3</h3><p class="muted">\u66f4\u65b0\u955c\u50cf\u65f6\u4f1a\u4fdd\u7559\u73b0\u6709\u914d\u7f6e\uff0c\u8fc7\u7a0b\u4e2d\u53ef\u67e5\u770b\u4efb\u52a1\u8fdb\u5ea6\u3002</p></div><div class="head-actions"><button class="primary" onclick="upd('astrbot')">\u66f4\u65b0 AstrBot</button><button class="primary" onclick="upd('napcat')">\u66f4\u65b0\u673a\u5668\u4eba</button><button class="success" onclick="upd('all')">\u66f4\u65b0\u5168\u90e8</button></div></div>${taskPanel()}<div class="card span12"><h3>\u5f53\u524d\u5bb9\u5668\u4fe1\u606f</h3><pre class="code">${esc(state.data?.docker?.containers||"\u6682\u65e0\u6570\u636e")}</pre></div></section>`}
async function upd(tar){return withBusy("\u6b63\u5728\u521b\u5efa\u66f4\u65b0\u4efb\u52a1",async()=>{const t=await req("/api/update",{method:"POST",body:JSON.stringify({target:tar})});toast("\u66f4\u65b0\u4efb\u52a1\u5df2\u521b\u5efa");showTask(t.id)})}
function account(){$("#content").innerHTML=`<section class="grid"><div class="card span6"><h3>\u4fee\u6539\u9762\u677f\u5bc6\u7801</h3><p class="muted">\u4fee\u6539\u7684\u662f Web \u63a7\u5236\u53f0\u767b\u5f55\u5bc6\u7801\uff0c\u4e0d\u5f71\u54cd AstrBot \u5bc6\u7801\u3002\u4fee\u6539\u6210\u529f\u540e\u6240\u6709\u8bbe\u5907\u90fd\u9700\u8981\u91cd\u65b0\u767b\u5f55\u3002</p><div class="file-cards"><label>\u5f53\u524d\u5bc6\u7801<input id="oldPwd" type="password" autocomplete="current-password"></label><label>\u65b0\u5bc6\u7801<input id="newPwd" type="password" autocomplete="new-password" placeholder="\u81f3\u5c11 10 \u4f4d\uff0c\u5efa\u8bae\u5305\u542b\u6570\u5b57\u548c\u5b57\u6bcd"></label><label>\u91cd\u590d\u65b0\u5bc6\u7801<input id="newPwd2" type="password" autocomplete="new-password"></label><button class="primary" onclick="changePassword()">\u4fdd\u5b58\u65b0\u5bc6\u7801\u5e76\u9000\u51fa\u6240\u6709\u8bbe\u5907</button></div></div><div class="card span6"><h3>\u8d26\u53f7\u8bf4\u660e</h3><div class="info-line"><b>\u5f53\u524d\u8d26\u53f7</b><span class="value">\u5df2\u767b\u5f55</span></div><div class="info-line"><b>\u914d\u7f6e\u6587\u4ef6</b><span class="value compact-url">/opt/astrbot/panel_config.json</span></div><div class="info-line"><b>\u5ba1\u8ba1\u65e5\u5fd7</b><span class="value compact-url">/opt/astrbot/logs/panel-audit.log</span></div></div></section>`}
async function changePassword(){const a=$("#newPwd").value,b=$("#newPwd2").value;if(a!==b)return toast("\u4e24\u6b21\u65b0\u5bc6\u7801\u4e0d\u4e00\u81f4");if(a.length<10)return toast("\u65b0\u5bc6\u7801\u81f3\u5c11\u9700\u8981 10 \u4f4d");const data=await req("/api/account/password",{method:"POST",body:JSON.stringify({old_password:$("#oldPwd").value,new_password:a})});toast("\u5bc6\u7801\u5df2\u4fee\u6539\uff0c\u6240\u6709\u8bbe\u5907\u5df2\u9000\u51fa\u767b\u5f55");sessionStorage.passwordChangedHint="1";setTimeout(()=>handleUnauthorized("\u5bc6\u7801\u5df2\u4fee\u6539\uff0c\u6240\u6709\u8bbe\u5907\u5df2\u9000\u51fa\u767b\u5f55\uff0c\u8bf7\u91cd\u65b0\u767b\u5f55\u3002"),650)}
async function settings(page="settings",seq=state.renderSeq){const c=await cachedReq("settings","/api/settings");if(!pageStillActive(page,seq))return;applyRuntimeConfig(c);const h=await cachedReq("https","/api/https/status").catch(()=>({}));if(!pageStillActive(page,seq))return;const wd=await cachedReq("watchdog","/api/watchdog/status").catch(()=>({service:"unknown",status:{}}));if(!pageStillActive(page,seq))return;$("#content").innerHTML=`<section class="grid"><div class="card span12"><h3>\u7cfb\u7edf\u8bbe\u7f6e</h3><div class="grid"><label class="span4">\u5b89\u88c5\u76ee\u5f55<input id="set_install_prefix" value="${q(c.install_prefix)}"></label><label class="span4">\u673a\u5668\u4eba\u7f51\u7edc\u540d\u79f0<input id="set_network_name" value="${q(c.network_name)}"></label><label class="span4">\u9ed8\u8ba4\u8fde\u63a5 Token<input id="set_default_reverse_ws_token" value="${q(c.default_reverse_ws_token)}"></label><label class="span4">\u4e0a\u4f20\u76ee\u5f55<input id="set_upload_dir" value="${q(c.upload_dir)}"></label><label class="span4">AstrBot \u63d2\u4ef6\u76ee\u5f55<input id="set_astrbot_plugin_dir" value="${q(c.astrbot_plugin_dir||'/opt/astrbot/data/plugins')}"></label><label class="span4">\u6389\u7ebf\u81ea\u52a8\u6062\u590d<select id="set_napcat_watchdog_enabled"><option value="true">\u5f00\u542f</option><option value="false">\u5173\u95ed</option></select></label><label class="span4">\u68c0\u6d4b\u95f4\u9694 / \u79d2<input id="set_napcat_watchdog_interval" type="number" min="30" max="3600" step="30" list="watchdogIntervals" value="${q(c.napcat_watchdog_interval||60)}"><datalist id="watchdogIntervals"><option value="30"><option value="60"><option value="120"><option value="300"></datalist></label><label class="span4">\u8fde\u7eed\u5f02\u5e38\u6b21\u6570<input id="set_napcat_watchdog_abnormal_threshold" type="number" min="1" max="10" value="${q(c.napcat_watchdog_abnormal_threshold||2)}"></label><label class="span4">10\u5206\u949f\u6700\u5927\u6062\u590d\u6b21\u6570<input id="set_napcat_recovery_max" type="number" min="0" max="20" value="${q(c.napcat_recovery_max||3)}"></label><label class="span4">\u6062\u590d\u7edf\u8ba1\u7a97\u53e3 / \u79d2<input id="set_napcat_recovery_window" type="number" min="60" max="86400" value="${q(c.napcat_recovery_window||600)}"></label><label class="span4">\u6062\u590d\u7b49\u5f85\u65f6\u95f4 / \u79d2<input id="set_napcat_recovery_wait" type="number" min="5" max="600" value="${q(c.napcat_recovery_wait||25)}"></label><label class="span4">\u6700\u5927\u4e0a\u4f20 MB<input id="set_max_upload_mb" type="number" value="${q(c.max_upload_mb)}"></label><label class="span4">\u516c\u7f51\u8bbf\u95ee\u5730\u5740<input id="set_public_base_url" value="${q(c.public_base_url||'')}" placeholder="\u901a\u5e38\u7559\u7a7a\uff0c\u81ea\u52a8\u8ddf\u968f\u5f53\u524d\u8bbf\u95ee\u57df\u540d"></label><label class="span4">QQ \u8fdc\u7a0b\u7533\u8bf7\u767b\u5f55<select id="set_linyu_remote_login_enabled"><option value="true">\u5f00\u542f</option><option value="false">\u5173\u95ed</option></select></label><label class="span4">\u8fdc\u7a0b API \u5730\u5740<input id="set_linyu_remote_server_url" value="${q(c.linyu_remote_server_url||'')}" placeholder="\u7559\u7a7a\u5219\u81ea\u52a8\u4f7f\u7528\u5f53\u524d\u9762\u677f\u5730\u5740"></label><label class="span4">\u4e3b\u4eba QQ<input id="set_linyu_remote_owner_ids" value="${q(c.linyu_remote_owner_ids||'')}" placeholder="\u591a\u4e2a\u7528\u9017\u53f7\u5206\u9694"></label><label class="span4">\u6302\u673a\u5668\u4eba QQ<input id="set_linyu_remote_bot_self_ids" value="${q(c.linyu_remote_bot_self_ids||'')}" placeholder="\u591a\u4e2a\u7528\u9017\u53f7\u5206\u9694"></label><label class="span4">\u5141\u8bb8\u7fa4\u53f7<input id="set_linyu_remote_allowed_groups" value="${q(c.linyu_remote_allowed_groups||'')}" placeholder="\u7559\u7a7a\u8868\u793a\u4e0d\u9650\u7fa4"></label><label class="span4">\u89e6\u53d1\u8bcd<input id="set_linyu_remote_triggers" value="${q(c.linyu_remote_triggers||'\u7533\u8bf7\u767b\u5f55')}" placeholder="\u591a\u4e2a\u7528\u9017\u53f7\u5206\u9694"></label><label class="span4">\u4e8c\u7ef4\u7801\u590d\u7528\u95f4\u9694 / \u79d2<input id="set_linyu_remote_qr_retry_seconds" type="number" min="10" max="3600" value="${q(c.linyu_remote_qr_retry_seconds||60)}"></label><label class="span4">\u7533\u8bf7\u51b7\u5374 / \u79d2<input id="set_linyu_remote_cooldown_seconds" type="number" min="0" max="86400" value="${q(c.linyu_remote_cooldown_seconds||300)}"></label><label class="span4">\u9762\u677f\u8d26\u53f7<input value="\u5df2\u9690\u85cf" disabled></label><div class="span4 info-line"><b>\u9762\u677f\u5bc6\u7801</b><span class="value">\u8bf7\u5230\u300c\u8d26\u53f7\u5b89\u5168\u300d\u9875\u4fee\u6539</span></div><label class="span4">\u4e3b\u9898\u8272<input id="set_theme_color" type="color" value="${q(c.theme_color||'#2563eb')}"></label><label class="span4">\u5141\u8bb8\u5371\u9669\u64cd\u4f5c<select id="set_allow_dangerous"><option value="false">\u5426</option><option value="true">\u662f</option></select></label></div><div class="toolbar"><button class="primary" onclick="saveSettings()">\u4fdd\u5b58\u8bbe\u7f6e</button><button onclick="restartWatchdog()">\u542f\u52a8 / \u91cd\u542f\u81ea\u52a8\u6062\u590d\u5b88\u62a4</button></div></div><div class="card span12"><h3>NapCat \u81ea\u52a8\u6062\u590d\u72b6\u6001</h3><div class="info-line"><b>\u5b88\u62a4\u670d\u52a1</b><span class="value">${safeText(wd.service||'unknown')}</span></div><pre class="code">${esc(JSON.stringify(wd.status||{},null,2))}</pre></div><div class="card span12"><h3>HTTPS / Let's Encrypt</h3><p class="muted">\u7ed1\u5b9a\u57df\u540d\u540e\uff0c\u9762\u677f\u4f1a\u6839\u636e\u5f53\u524d Host\u3001Forwarded Header\u3001Cloudflare / Nginx / Caddy \u81ea\u52a8\u751f\u6210\u8bbf\u95ee\u5730\u5740\u3002</p><div class="grid"><label class="span4">\u57df\u540d<input id="httpsDomain" placeholder="panel.example.com" value="${q(h.domain||'')}"></label><label class="span4">\u90ae\u7bb1<input id="httpsEmail" placeholder="admin@example.com"></label><div class="span4"><div class="info-line"><b>\u72b6\u6001</b><span class="value">${h.enabled?"\u5df2\u542f\u7528":"\u672a\u542f\u7528"}</span></div></div></div><div class="toolbar"><button class="primary" onclick="setupHttps()">\u81ea\u52a8\u914d\u7f6e HTTPS</button>${h.url?`<a class="link-pill" href="${safeHref(h.url)}" target="_blank" rel="noopener noreferrer">${safeText(h.url)}</a>`:""}</div></div><div class="card span12"><h3>\u5f53\u524d\u914d\u7f6e</h3><pre class="code">${esc(JSON.stringify(c,null,2))}</pre></div></section>`;$("#set_allow_dangerous").value=String(c.allow_dangerous);$("#set_napcat_watchdog_enabled").value=String(c.napcat_watchdog_enabled!==false);$("#set_linyu_remote_login_enabled").value=String(c.linyu_remote_login_enabled!==false);renderDeviceCard();reportDeviceInfo()}
async function saveSettings(){let ids=["install_prefix","network_name","default_reverse_ws_token","upload_dir","astrbot_plugin_dir","max_upload_mb","public_base_url","linyu_remote_server_url","linyu_remote_owner_ids","linyu_remote_bot_self_ids","linyu_remote_allowed_groups","linyu_remote_triggers","linyu_remote_qr_retry_seconds","linyu_remote_cooldown_seconds","theme_color","napcat_watchdog_interval","napcat_watchdog_abnormal_threshold","napcat_recovery_max","napcat_recovery_window","napcat_recovery_wait"];let body={};ids.forEach(k=>body[k]=$(`#set_${k}`).value);["max_upload_mb","napcat_watchdog_interval","napcat_watchdog_abnormal_threshold","napcat_recovery_max","napcat_recovery_window","napcat_recovery_wait","linyu_remote_qr_retry_seconds","linyu_remote_cooldown_seconds"].forEach(k=>body[k]=Number(body[k]));body.allow_dangerous=$("#set_allow_dangerous").value==="true";body.napcat_watchdog_enabled=$("#set_napcat_watchdog_enabled").value==="true";body.linyu_remote_login_enabled=$("#set_linyu_remote_login_enabled").value==="true";await req("/api/settings",{method:"POST",body:JSON.stringify(body)});applyRuntimeConfig(body);invalidateCache("settings","watchdog");toast("\u8bbe\u7f6e\u5df2\u4fdd\u5b58\uff0cQQ \u8fdc\u7a0b\u767b\u5f55\u63d2\u4ef6\u914d\u7f6e\u5df2\u540c\u6b65")}
async function setupHttps(){const domain=$("#httpsDomain").value.trim(),email=$("#httpsEmail").value.trim();if(!domain)return toast("\u8bf7\u8f93\u5165\u57df\u540d");const t=await req("/api/https/setup",{method:"POST",body:JSON.stringify({domain,email})});toast("HTTPS \u914d\u7f6e\u4efb\u52a1\u5df2\u5f00\u59cb");showTask(t.id)}
async function restartWatchdog(){return withBusy("\u6b63\u5728\u91cd\u542f\u5b88\u62a4",async()=>{await req("/api/watchdog/restart",{method:"POST",body:"{}"});toast("NapCat \u81ea\u52a8\u6062\u590d\u5b88\u62a4\u5df2\u542f\u52a8");settings()})}
function visibleTasks(){return (state.tasks||[]).filter(t=>!["success","failed","cancelled"].includes(t.status)).slice(-6).reverse()}
function taskPanel(){return `<div class="card span12 task-card task-floating task-hidden"><div class="task-head"><div><h3>\u4efb\u52a1\u8fdb\u5ea6</h3><p class="muted">\u6b63\u5728\u5904\u7406\u7684\u4efb\u52a1\u4f1a\u56fa\u5b9a\u5728\u8fd9\u91cc\u3002</p></div></div><div id="tasks" class="file-cards task-list"></div></div>`}
async function loadTasks(){try{state.tasks=await req("/api/tasks");const el=$("#tasks");if(!el)return;const rows=visibleTasks(),card=el.closest(".task-card"),sig=rows.map(t=>`${t.id}:${t.status}:${t.progress}`).join("|");card?.classList.toggle("task-hidden",!rows.length);if(el.dataset.renderSig===sig)return;state.tasksRenderSig=sig;el.dataset.renderSig=sig;el.innerHTML=rows.map(t=>`<div class="file-card task-item" data-task-id="${q(t.id)}"><div><b>${safeText(t.title)}</b><div class="muted">${taskStatusText(t.status)} / ${safeText(t.updated_at)}</div><div class="progress"><span style="width:${t.progress}%"></span></div></div><button class="tiny" onclick="showTask('${q(t.id)}')">查看</button></div>`).join("")}catch{}}
async function showTask(id){state.taskModalId=id;const draw=async()=>{const t=await req(`/api/tasks/${id}`);const html=`<div id="taskModalInner" class="task-modal"><h3 id="taskTitle">${safeText(t.title)}</h3><p id="taskMeta" class="muted">\u72b6\u6001: ${taskStatusText(t.status)} / \u8fdb\u5ea6: ${t.progress}%</p><div class="progress"><span id="taskProgress" style="width:${t.progress}%"></span></div><pre id="taskLog" class="code">${esc((t.logs||[]).join("\n"))}</pre></div>`;if($("#modal")?.classList.contains("hidden")||state.taskModalId!==id||!$("#taskModalInner")){openModal(html,()=>closeModal(),{confirmText:"\u786e\u5b9a",cancelText:"\u53d6\u6d88"})}else{$("#taskTitle").textContent=t.title;$("#taskMeta").textContent=`\u72b6\u6001: ${taskStatusText(t.status)} / \u8fdb\u5ea6: ${t.progress}%`;$("#taskProgress").style.width=t.progress+"%";$("#taskLog").textContent=(t.logs||[]).join("\n")}const done=t.status==="success"||t.status==="failed";const ok=$("#modalOk");if(ok&&$("#taskModalInner")){ok.style.display="";ok.textContent=done?"\u5b8c\u6210":"\u786e\u5b9a";ok.className="primary";ok.onclick=()=>closeModal()}const cancel=$("#modal .modal-actions button:first-child");if(cancel&&$("#taskModalInner"))cancel.textContent=done?"\u5173\u95ed":"\u53d6\u6d88";const box=$("#taskLog");if(box)box.scrollTop=box.scrollHeight;if(t.status==="success"){toast("\u4efb\u52a1\u5b8c\u6210");state.taskModalId=null;invalidateCache("dashboard","napcat","pool","astrbot");refresh(true,true);return true}if(t.status==="failed"){toast("\u4efb\u52a1\u5931\u8d25\uff0c\u8bf7\u770b\u8f93\u51fa");state.taskModalId=null;return true}return false};if(await draw())return;const timer=setInterval(async()=>{try{if($("#modal")?.classList.contains("hidden")||state.taskModalId!==id){clearInterval(timer);return}if(await draw())clearInterval(timer)}catch{clearInterval(timer)}},1200)}
function openModal(html,ok,options={}){$("#modalBody").innerHTML=html;const m=$("#modal"),okBtn=$("#modalOk"),cancel=$("#modal .modal-actions button:first-child");if(okBtn){okBtn.textContent=options.confirmText||"\u786e\u5b9a";okBtn.className=options.confirmClass||"primary";okBtn.disabled=false}if(cancel){cancel.textContent=options.cancelText||"\u53d6\u6d88";cancel.disabled=false}if(m.classList.contains("hidden"))lockScroll();m.classList.remove("hidden");requestAnimationFrame(()=>m.classList.add("show"));okBtn.style.display=ok?"":"none";okBtn.onclick=ok?async()=>{if(okBtn.disabled)return;const old=okBtn.innerHTML;try{okBtn.disabled=true;if(cancel)cancel.disabled=true;okBtn.classList.add("is-busy");okBtn.innerHTML=`<span class="spin"></span>${options.loadingText||"\u5904\u7406\u4e2d"}`;await ok()}catch(e){toast(e.message||"\u64cd\u4f5c\u5931\u8d25");okBtn.disabled=false;if(cancel)cancel.disabled=false;okBtn.classList.remove("is-busy");okBtn.innerHTML=old}}:(()=>{})}

function closeModal(){state.taskModalId=null;if(state.qrTimer){clearInterval(state.qrTimer);state.qrTimer=null}const m=$("#modal");const wasOpen=!m.classList.contains("hidden");m.classList.remove("show");setTimeout(()=>m.classList.add("hidden"),160);if(wasOpen)unlockScroll()}
function confirmDanger({title="\u786e\u8ba4\u6267\u884c\u64cd\u4f5c\uff1f",name="",message="",confirmText="\u786e\u8ba4",cancelText="\u53d6\u6d88",onConfirm}){openModal(`<div class="confirm-box"><div class="confirm-icon">!</div><div><h3>${safeText(title)}</h3><p class="muted">${safeText(message)}</p>${name?`<div class="confirm-target"><span>\u5b9e\u4f8b\u540d\u79f0</span><b>${safeText(name)}</b></div>`:""}</div></div>`,async()=>{closeModal();await onConfirm?.()},{confirmText,cancelText,confirmClass:"danger"})}
function confirmDo(msg,word,fn){openModal(`<div class="confirm-box"><div class="confirm-icon">!</div><div><h3>\u4e8c\u6b21\u786e\u8ba4</h3><p class="muted">${safeText(msg)}</p><input id="confirmInput" class="confirm-input" placeholder="${q(word)}"></div></div>`,async()=>{if($("#confirmInput").value!==word)return toast("\u786e\u8ba4\u6587\u5b57\u4e0d\u5339\u914d");closeModal();await fn()},{confirmClass:"danger"})}
function esc(s){return String(s??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[m]))}

function jsq(s){return String(s??"").replace(/\\/g,"\\\\").replace(/'/g,"\\'").replace(/[\r\n]+/g," ")}
function q(s){return esc(jsq(s))}
function safeHref(u){try{const x=new URL(String(u||""),location.href);return ["http:","https:"].includes(x.protocol)?esc(x.href):"#"}catch{return "#"}}
function safeText(s){return esc(s)}

function deviceLabel(){const d=state.device||detectDevice(),sys=d.system||{},br=d.browser||{},dev=d.device||{};const system=sys.ipadOS?"iPadOS":sys.ios?"iOS":sys.android?"Android":sys.windows?"Windows":sys.macos?"macOS":sys.linux?"Linux":"Unknown";const browser=br.wechat?"\u5fae\u4fe1\u6d4f\u89c8\u5668":br.qq?"QQ \u6d4f\u89c8\u5668":br.quark?"\u5938\u514b":br.uc?"UC \u6d4f\u89c8\u5668":br.edge?"Edge":br.firefox?"Firefox":br.chrome?"Chrome":br.safari?"Safari":"Unknown";const type=dev.mobile?"\u624b\u673a":dev.tablet?"\u5e73\u677f":"\u684c\u9762\u7aef";return {system,browser,type}}
function deviceInfoForCopy(){applyDeviceClasses();const d=state.device||detectDevice(),l=deviceLabel();return {time:new Date().toISOString(),system:l.system,browser:l.browser,device_type:l.type,screen:d.screen,capabilities:d.capabilities,raw:d.raw,classes:[...document.documentElement.classList].filter(x=>/^(os-|browser-|device-|touch-device|small-screen|landscape|portrait|ios-|ipad-|standalone)/.test(x))}}
function renderDeviceCard(){try{const sec=$("#content section.grid");if(!sec||$("#deviceInfoCard"))return;const d=state.device||detectDevice(),l=deviceLabel();const html=`<div id="deviceInfoCard" class="card span12 device-info-card"><div class="section-head"><div><h3>\u8bbe\u5907\u73af\u5883\u68c0\u6d4b</h3><p class="muted">\u4ec5\u7528\u4e8e iOS Safari \u517c\u5bb9\u5224\u65ad\u548c\u95ee\u9898\u6392\u67e5\uff0c\u4e0d\u751f\u6210\u552f\u4e00\u8bbe\u5907 ID\u3002</p></div><button class="soft" onclick="copyDeviceInfo()">\u590d\u5236\u8bbe\u5907\u4fe1\u606f</button></div><div class="device-grid"><div><b>\u7cfb\u7edf</b><span>${safeText(l.system)}</span></div><div><b>\u6d4f\u89c8\u5668</b><span>${safeText(l.browser)}</span></div><div><b>\u8bbe\u5907\u7c7b\u578b</b><span>${safeText(l.type)}</span></div><div><b>\u5c4f\u5e55</b><span>${d.screen.width} x ${d.screen.height}</span></div><div><b>\u7a97\u53e3</b><span>${d.screen.innerWidth} x ${d.screen.innerHeight}</span></div><div><b>DPR</b><span>${d.screen.dpr}</span></div><div><b>\u6700\u5927\u89e6\u6478\u70b9</b><span>${d.raw.maxTouchPoints||0}</span></div><div><b>iOS Safari</b><span>${d.system.ios&&d.browser.safari?"\u662f":"\u5426"}</span></div><div><b>iPadOS</b><span>${d.system.ipadOS?"\u662f":"\u5426"}</span></div><div><b>PWA</b><span>${d.capabilities.standalone?"\u662f":"\u5426"}</span></div><div><b>\u526a\u8d34\u677f</b><span>${d.capabilities.clipboard?"\u652f\u6301":"\u964d\u7ea7\u652f\u6301"}</span></div><div><b>\u6bdb\u73bb\u7483</b><span>${d.capabilities.backdropFilter?"\u652f\u6301":"\u4e0d\u652f\u6301"}</span></div></div><details class="ua-details"><summary>User-Agent</summary><pre class="code selectable">${esc(d.raw.userAgent||"")}</pre></details></div>`;sec.insertAdjacentHTML("beforeend",html)}catch(e){console.debug(e)}}
async function copyDeviceInfo(){await copyText(JSON.stringify(deviceInfoForCopy(),null,2))}
async function reportDeviceInfo(){try{const d=deviceInfoForCopy();await req("/api/device/report",{method:"POST",body:JSON.stringify({system:d.system,browser:d.browser,device_type:d.device_type,screen:`${d.screen.width}x${d.screen.height}`,viewport:`${d.screen.innerWidth}x${d.screen.innerHeight}`,dpr:d.screen.dpr,user_agent:d.raw.userAgent})})}catch{}}

